    plan.workerd, "serve", join(directory, "runtime.capnp"), "--experimental", "--import-path", "/",
    "--socket-addr", "public=127.0.0.1:18992", "--external-addr", `mock=127.0.0.1:${mock.port}`,
  ];
  result.argv = argv;
  child = Bun.spawn(["/usr/bin/python3", plan.gateway_bootstrap, ...argv], {
    cwd: directory,
    env: { PATH: "/usr/bin:/bin", TZ: "UTC" },
    stdin: "pipe",
    stdout: "pipe",
    stderr: Bun.file(join(directory, "workerd.stderr.log")),
  });
  const bootstrap = createConformanceJournal();
  stdoutDrain = (async () => {
    let pending = "";
    let raw = "";
    for await (const chunk of child!.stdout) {
      const text = new TextDecoder().decode(chunk);
      raw += text;
      assert(raw.length <= 65_536);
      pending += text;
      for (;;) {
        const index = pending.indexOf("\n");
        if (index < 0) break;
        const line = pending.slice(0, index);
        pending = pending.slice(index + 1);
