  for (const [name, expected] of Object.entries({ "memory.max": "536870912", "memory.swap.max": "0", "cpu.max": "100000 100000" })) {
    assert.equal((await readFile("/sys/fs/cgroup" + placement + "/" + name, "utf8")).trim(), expected);
  }
  result.gatewayPlacement = placement;
  child.stdin.write("launch\n");
  child.stdin.end();
  const deadline = performance.now() + 10_000;
  while (performance.now() < deadline) {
    assert.equal(child.exitCode, null, "workerd exited during startup");
    try {
      const response = await fetch("http://127.0.0.1:18992/health");
      if (response.status === 200) {
        const body = await response.text();
        assert(body.includes(plan.expected_sha));
        assert.equal(response.headers.get("x-uos-git-sha"), plan.expected_sha);
