  }
  throw new Error("workerd health deadline exceeded");
}

async function meaningful(stream: Awaited<ReturnType<typeof openConformanceResponse>>, type: string, turn: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const observed = stream.waitFor(type).then((event) => ({ event, atMs: performance.now() }), () => null);
  const event = await Promise.race([observed, new Promise<null>((resolve) => { timer = setTimeout(() => resolve(null), 2_000); })]);
  clearTimeout(timer);
  if (!event) {
    failedAssertions.push({ assertion: "meaningful_delta_before_upstream_continuation", type, turn, atMs: performance.now(), timeoutMs: 2_000 });
    await save("failed-assertions.json", failedAssertions);
  }
  return event;
}

function acknowledge(mock: Awaited<ReturnType<typeof startConformanceMock>>, turn: number, type: string, receipt: Awaited<ReturnType<typeof meaningful>>) {
  if (diagnosticOpenTurns.has(turn)) {
    if (receipt) mock.journal.add("late_client_delta_after_diagnostic_release", { turn, actualClientReceipt: true, comparableIncrementalPass: false });
    return;
  }
  if (receipt) mock.receipt(turn, receipt.event);
  else {
    mock.journal.add("diagnostic_release_without_client_receipt", { turn, atMs: performance.now(), actualClientReceipt: false });
    mock.receipt(turn, { type, delta: "[diagnostic continuation; no client delta observed]", actualClientReceipt: false, diagnosticContinuation: true });
  }
}

async function openObservedResponse(endpoint: string, token: string, body: Record<string, unknown>) {
  const turn = ++openingSequence;
  const opening = openConformanceResponse(endpoint, token, body);
  let timer: ReturnType<typeof setTimeout> | undefined;
  const stream = await Promise.race([opening, new Promise<null>((resolve) => { timer = setTimeout(() => resolve(null), 2_000); })]);
  clearTimeout(timer);
  if (stream) return stream;
  failedAssertions.push({ assertion: "response_headers_before_upstream_continuation", turn, timeoutMs: 2_000, atMs: performance.now() });
  await save("failed-assertions.json", failedAssertions);
  await snapshot("diagnostic-held-without-response-headers");
  acknowledge(mocks[0], turn, turn === 1 ? "response.function_call_arguments.delta" : "response.output_text.delta", null);
  diagnosticOpenTurns.add(turn);
  return await opening;
}

async function drainCompletedMockBatch(): Promise<void> {
  const mock = mocks[0];
  assert(mock.calls.every((call) => call.response && call.response.chunksBase64.length >= 2), "Drain only fully ended producers");
  const entries = mock.journal.entries.map((entry, index) => ({ archiveSequence: archivedChronology.length + index + 1, ...structuredClone(entry) }));
  if (entries.length) await appendFile(join(directory, "mock-chronology.ndjson"), entries.map((entry) => JSON.stringify(entry)).join("\n") + "\n");
  archivedChronology.push(...entries);
  mock.journal.entries.splice(0);
}

function checkReceiptOrder(mock: Awaited<ReturnType<typeof startConformanceMock>>): void {
  for (const turn of [1, 2]) {
    const first = mock.journal.entries.findIndex((entry) => entry.kind === "provider_first_delta" && entry.detail.turn === turn);
    const receipt = mock.journal.entries.findIndex((entry) => entry.kind === "client_received_delta" && entry.detail.turn === turn);
    const resumed = mock.journal.entries.findIndex((entry) => entry.kind === "provider_resumed" && entry.detail.turn === turn);
    assert(first >= 0 && first < receipt && receipt < resumed, "Upstream continuation requires actual meaningful client receipt");
  }
}

function accumulate(capture: ConformanceWireCapture): Record<string, unknown>[] {
  const items: Record<string, unknown>[] = [];
  for (const event of capture.events) {
    const index = typeof event.output_index === "number" ? event.output_index : -1;
    if (event.type === "response.output_item.added") {
      assert.equal(index, items.length, "Each announcement must match its client accumulation position");
      items.push(structuredClone(conformanceRecord(event.item)));
    }
    if (["response.function_call_arguments.delta", "response.output_text.delta"].includes(String(event.type))) {
      const item = items[index];
      assert(item, "A delta must reference an announced item");
      assert.equal(event.item_id, item.id);
      if (event.type === "response.function_call_arguments.delta") item.arguments = String(item.arguments ?? "") + event.delta;
      else {
        const content = item.content as Record<string, unknown>[];
        const part = content[Number(event.content_index)];
        assert(part, "Text must reference an announced content part");
        part.text = String(part.text ?? "") + event.delta;
      }
    }
    if (event.type === "response.content_part.added") {
      const content = items[index]?.content as Record<string, unknown>[];
      assert(content);
      assert.equal(event.content_index, content.length);
      content.push(structuredClone(conformanceRecord(event.part)));
    }
    if (event.type === "response.output_item.done") {
      const item = conformanceRecord(event.item);
      assert.equal(items[index]?.id, item.id);
      if (item.type === "function_call") assert.equal(items[index].arguments, item.arguments);
      if (item.type === "message") {
        const current = items[index].content as Record<string, unknown>[];
        const complete = item.content as Record<string, unknown>[];
        assert.deepEqual(current.map((part) => part.text), complete.map((part) => part.text));
      }
      items[index] = structuredClone(item);
    }
  }
  assert.deepEqual(completedConformanceResponse(capture).output, items, "Terminal output must equal accumulated completed items");
  return items;
}

async function flow(index: number, ready: { count: number; release: ReturnType<typeof Promise.withResolvers<void>> }): Promise<void> {
  const request = conformanceRequest();
  if (plan.scenario === "parallel") {
    const input = request.input as Record<string, unknown>[];
    input[1] = { ...input[1], content: `Run the fixture tool. [comparison-flow:${index}]` };
  }
  const first = await openObservedResponse("http://127.0.0.1:18992", "fixture-access", request);
  streams.push(first);
  const delta = await meaningful(first, "response.function_call_arguments.delta", 1);
  ready.count++;
  if (ready.count === mocks.length) {
    await snapshot(mocks.length === 2 ? "loaded-two-streams" : "loaded-one-stream");
    ready.release.resolve();
  }
  await ready.release.promise;
  acknowledge(mocks[index], 1, "response.function_call_arguments.delta", delta);
  const tool = await first.finished;
  captures.push(tool);
  const terminal = completedConformanceResponse(tool);
  accumulate(tool);
  const toolUsage = conformanceRecord(terminal.usage);
  assert.deepEqual([toolUsage.input_tokens, toolUsage.output_tokens, toolUsage.total_tokens], [11, 5, 16]);
  assert.equal(conformanceRecord(toolUsage.input_tokens_details).cached_tokens, 0);
  const output = terminal.output as Record<string, unknown>[];
  const call = output.find((item) => item.type === "function_call");
  assert(call);
  assert.equal(call.call_id, CONFORMANCE_CALL_ID);
  assert.equal(call.arguments, CONFORMANCE_ARGUMENTS);
  const second = await openObservedResponse("http://127.0.0.1:18992", "fixture-access", conformanceContinuation(request, tool));
  streams.push(second);
  acknowledge(mocks[index], 2, "response.output_text.delta", await meaningful(second, "response.output_text.delta", 2));
  const answer = await second.finished;
  captures.push(answer);
  const final = completedConformanceResponse(answer);
  accumulate(answer);
  const finalUsage = conformanceRecord(final.usage);
  assert.deepEqual([finalUsage.input_tokens, finalUsage.output_tokens, finalUsage.total_tokens], [23, 7, 30]);
  assert.equal("input_tokens_details" in finalUsage, false, "Missing cache usage must remain distinct from explicit zero");
  assert(JSON.stringify(final.output).includes(CONFORMANCE_FINAL));
  assert.equal(mocks[index].calls.length, 2);
  const upstream = conformanceRecord(JSON.parse(mocks[index].calls[1].body));
  assert(JSON.stringify(upstream.messages).includes("fixture-tool-ok"));
  assert(JSON.stringify(upstream.messages).includes(CONFORMANCE_CALL_ID));
  if (!failedAssertions.length) checkReceiptOrder(mocks[index]);
}

function providerTurn(stream: Awaited<ReturnType<typeof openConformanceResponse>>): number {
  const id = stream.capture.headers["x-uos-provider-request-id"];
  assert(id && /^fixture-provider-\d+$/.test(id));
  return Number(id.slice("fixture-provider-".length));
}

async function metrics(count: number): Promise<void> {
  const mock = mocks[0];
  const warmup = await openObservedResponse("http://127.0.0.1:18992", "fixture-access", conformanceRequest());
  streams.push(warmup);
  acknowledge(mock, 1, "response.function_call_arguments.delta", await meaningful(warmup, "response.function_call_arguments.delta", 1));
  captures.push(await warmup.finished);
  accumulate(captures.at(-1)!);
  await pause(2_000);
  await snapshot("warm-idle-after-warmup-2s");
  const openings = await Promise.all(Array.from({ length: count }, async () => { const startedAtMs = performance.now(); const stream = await openObservedResponse("http://127.0.0.1:18992", "fixture-access", conformanceRequest()); return { stream, startedAtMs }; }));
  const starts = openings.map((opening) => opening.startedAtMs);
  const loaded = openings.map((opening) => opening.stream);
  streams.push(...loaded);
  const receipts = await Promise.all(loaded.map((stream) => meaningful(stream, "response.output_text.delta", providerTurn(stream))));
  result.primaryTtfd = receipts.map((receipt, index) => ({ request: index, actualMeaningfulDelta: Boolean(receipt), ttfdMs: receipt ? receipt.atMs - starts[index] : null }));
  await snapshot(`loaded-${count}-streams-before-receipt`);
  await pause(1_000);
  await snapshot(`loaded-${count}-streams-held-1s`);
  loaded.forEach((stream, index) => acknowledge(mock, providerTurn(stream), "response.output_text.delta", receipts[index]));
  for (const stream of loaded) { const capture = await stream.finished; captures.push(capture); accumulate(capture); }
  await pause(2_000);
  await snapshot("postload-idle-2s");

}

async function latency(count: number): Promise<void> {
  const mock = mocks[0];
  for (const type of ["response.function_call_arguments.delta", "response.output_text.delta"]) {
    const stream = await openObservedResponse("http://127.0.0.1:18992", "fixture-access", conformanceRequest());
    streams.push(stream);
    const turn = providerTurn(stream);
    acknowledge(mock, turn, type, await meaningful(stream, type, turn));
    const capture = await stream.finished; captures.push(capture); accumulate(capture);
  }
  await pause(2_000);
  await snapshot("latency-warm-idle-after-two-warmups-2s");
  if (failedAssertions.length) { result.ttfd = { successful: 0, p95Ms: null, comparableSuccessMetric: false, reason: "warmup incremental assertion failed; no replacement generations" }; return; }
  await drainCompletedMockBatch();
  const samples: Record<string, unknown>[] = [];
  const benchmarkStart = performance.now();
  const deadline = benchmarkStart + 30_000;
  for (let offset = 0; offset < 20; offset += count) {
    if (performance.now() >= deadline) { result.benchmarkLimit = "30s runtime bound"; break; }
    assert(child);
    const group = (await readFile(`/proc/${child.pid}/cgroup`, "utf8")).trim().slice(3);
    const current = Number(await readFile("/sys/fs/cgroup" + group + "/memory.current", "utf8"));
    if (current >= 0.9 * 512 * 1024 * 1024) { result.benchmarkLimit = "gateway memory margin below10percent"; break; }
    const openings = await Promise.all(Array.from({ length: count }, async () => { const startedAtMs = performance.now(); const stream = await openObservedResponse("http://127.0.0.1:18992", "fixture-access", conformanceRequest()); return { stream, startedAtMs }; }));
    const begin = openings.map((opening) => opening.startedAtMs);
    const batch = openings.map((opening) => opening.stream);
    streams.push(...batch);
    const deltas = await Promise.all(batch.map((stream) => meaningful(stream, "response.output_text.delta", providerTurn(stream))));
    batch.forEach((stream, index) => acknowledge(mock, providerTurn(stream), "response.output_text.delta", deltas[index]));
    for (let index = 0; index < batch.length; index++) {
      const capture = await batch[index].finished;
      captures.push(capture);
      accumulate(capture);
      samples.push({ sample: offset + index + 1, actualMeaningfulDelta: Boolean(deltas[index]), ttfdMs: deltas[index] ? deltas[index]!.atMs - begin[index] : null, requestId: capture.headers["x-uos-request-id"] });
    }
    await save("ttfd-samples.json", samples);
    await drainCompletedMockBatch();
  }
  const successful = samples.filter((sample) => sample.actualMeaningfulDelta === true).map((sample) => Number(sample.ttfdMs)).sort((a, b) => a - b);
  result.ttfd = { concurrency: count, issued: samples.length, successful: successful.length, warmupExcluded: true, percentileMethod: "nearest-rank ceil(p*N), measured client request start to first actual meaningful text delta", elapsedMs: performance.now() - benchmarkStart, p50Ms: successful.length >= 20 && !failedAssertions.length ? successful[Math.ceil(0.5 * successful.length) - 1] : null, p95Ms: successful.length >= 20 && !failedAssertions.length ? successful[Math.ceil(0.95 * successful.length) - 1] : null, comparableSuccessMetric: successful.length >= 20 && !failedAssertions.length };
  await snapshot("after-benchmark");
}

